export const deleteAccount = mutation({
  args: {},
  returns: v.object({
    deleted: v.record(v.string(), v.number()),
    identityPurged: v.boolean(),
    emailProvided: v.boolean(),
    deletionScheduled: v.boolean(),
  }),
  handler: async (ctx) => {
    const identity = await ctx.auth.getUserIdentity();
    if (!identity) throw new Error("Not signed in");
    const ownerId = identity.tokenIdentifier;
    const productSubject = identity.subject || identity.tokenIdentifier;
    const email = identity.email?.trim().toLowerCase();
    const identityPurged = await scheduleAccountDeletion(ctx, {
      ownerId,
      productSubject,
      email,
      userId: identity.subject,
    });
    return {
      deleted: {},
      identityPurged,
      emailProvided: !!email,
      deletionScheduled: true,
    };
  },
});

/**
 * Start (or resume) the resumable deletion job for one account and purge its
 * Better Auth identity right away so no session survives the request.
 */
export async function scheduleAccountDeletion(
  ctx: MutationCtx,
  job: {
    ownerId: string;
    productSubject: string;
    email?: string;
    userId?: string;
  },
): Promise<boolean> {
  const { ownerId, productSubject, email, userId } = job;
  const existing = await ctx.db
    .query("accountDeletionJobs")
    .withIndex("by_ownerId", (q) => q.eq("ownerId", ownerId))
    .unique();
  const now = Date.now();
  const jobId =
    existing?._id ??
    (await ctx.db.insert("accountDeletionJobs", {
      ownerId,
      productSubject,
      email,
      phase: 0,
      deletedCount: 0,
      createdAt: now,
      updatedAt: now,
    }));
  let identityPurged = false;
  if (userId) {
    try {
      identityPurged = await purgeBetterAuthIdentity(ctx, userId);
    } catch (error) {
      console.error("[twyne:account] auth identity purge failed:", error);
    }
  }
  await ctx.scheduler.runAfter(0, continueDeletionReference, { jobId });
  return identityPurged;
}

export const continueDeletion = internalMutation({
  args: { jobId: v.id("accountDeletionJobs") },
  returns: v.null(),
  handler: async (ctx, { jobId }) => {
    const job = await ctx.db.get("accountDeletionJobs", jobId);
    if (!job) return null;
    const phase = PHASES[job.phase];
    if (!phase) {
      await ctx.db.delete(job._id);
      return null;
    }
    const count = await deletePhase(ctx, phase, job);
    await ctx.db.patch(job._id, {
      phase: count < DELETE_BATCH_SIZE ? job.phase + 1 : job.phase,
      deletedCount: job.deletedCount + count,
      updatedAt: Date.now(),
    });
    await ctx.scheduler.runAfter(0, continueDeletionReference, { jobId });
    return null;
  },
});

/** Remove the Better Auth user row plus its sessions and linked accounts. */
export async function purgeBetterAuthIdentity(
  ctx: MutationCtx,
  userId: string,
) {
  const adapter = (
    components.betterAuth as unknown as {
      adapter: { findOne: unknown; deleteMany: unknown };
    }
  ).adapter;
  const user = (await ctx.runQuery(
    adapter.findOne as never,
    {
      model: "user",
      where: [{ field: "_id", operator: "eq", value: userId }],
    } as never,
  )) as { _id?: string } | null;
  if (!user?._id) return false;
  for (const model of ["session", "account"]) {
    await ctx.runMutation(
      adapter.deleteMany as never,
      {
        input: {
          model,
          where: [{ field: "userId", operator: "eq", value: user._id }],
        },
        paginationOpts: { cursor: null, numItems: 1000 },
      } as never,
    );
  }
  await ctx.runMutation(
    adapter.deleteMany as never,
    {
      input: {
        model: "user",
        where: [{ field: "_id", operator: "eq", value: user._id }],
      },
      paginationOpts: { cursor: null, numItems: 1000 },
    } as never,
  );
  return true;
}

