    updatedAt: v.number(),
  })
    .index("by_userId", ["userId"])
    .index("by_userId_streamId", ["userId", "streamId"])
    .index("by_userId_streamId_personaId", ["userId", "streamId", "personaId"])
    .index("by_updatedAt", ["updatedAt"]),

  folios: defineTable({
